// ─── SCENE 2: Configure ───────────────────────────────────────────────────────

const ACTORS = [
  { name: "RAG Web Browser", desc: "Browse & extract web content", icon: "🌐", delay: 30 },
  { name: "Google Search Scraper", desc: "Search results at scale", icon: "🔍", delay: 65 },
  { name: "Instagram Scraper", desc: "Profiles, posts & reels", icon: "📸", delay: 100 },
];

const BASE_URL = "https://mcp.apify.com/sse?actors=";

const ActorRow: React.FC<{
  actor: (typeof ACTORS)[number];
  checked: boolean;
  checkFrame: number;
}> = ({ actor, checked, checkFrame }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const rowProgress = spring({ frame, fps: f, delay: actor.delay, config: { damping: 200 } });
  const checkProgress = checked
    ? spring({ frame: Math.max(0, frame - checkFrame), fps: f, delay: 0, config: { damping: 14, stiffness: 280 } })
    : 0;

  const checkScale = interpolate(checkProgress, [0, 0.5, 0.8, 1], [0, 1.3, 0.9, 1]);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 40,
        padding: "36px 48px",
        backgroundColor: checked ? "rgba(0,200,80,0.06)" : COLORS.cardBg,
        borderRadius: 20,
        border: `2px solid ${checked ? "rgba(0,200,80,0.3)" : COLORS.cardBorder}`,
        opacity: rowProgress,
        transform: `translateX(${interpolate(rowProgress, [0, 1], [-60, 0])}px)`,
        transition: "background-color 0.2s, border-color 0.2s",
      }}
    >
      {/* Icon */}
      <div style={{ fontSize: 56 }}>{actor.icon}</div>

      {/* Text */}
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 42, fontWeight: 700, color: COLORS.white }}>{actor.name}</div>
        <div style={{ fontSize: 32, color: COLORS.muted, marginTop: 6 }}>{actor.desc}</div>
      </div>

      {/* Checkbox */}
      <div
        style={{
          width: 52,
          height: 52,
          borderRadius: 14,
          border: `3px solid ${checked ? COLORS.apifyGreen : "rgba(255,255,255,0.25)"}`,
          backgroundColor: checked ? COLORS.apifyGreen : "transparent",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${checkScale})`,
        }}
      >
        {checked && (
          <svg width="28" height="28" viewBox="0 0 28 28" fill="none">
            <path
              d="M5 14 L11 20 L23 8"
              stroke="black"
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </div>
    </div>
  );
};

const Scene2Configure: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const titleProgress = spring({ frame, fps: f, delay: 5, config: { damping: 200 } });

  // Actors get checked at staggered frames
  const actor0Checked = frame >= 40;
  const actor1Checked = frame >= 78;
  const actor2Checked = frame >= 116;

  // URL typewriter
  const urlSegments = [
    { text: "apify~rag-web-browser", startFrame: 50 },
    { text: "+apify~google-search-scraper", startFrame: 88 },
    { text: "+apify~instagram-scraper", startFrame: 124 },
  ];

  let urlText = BASE_URL;
  for (const seg of urlSegments) {
    if (frame >= seg.startFrame) {
      const elapsed = frame - seg.startFrame;
      const charsToShow = Math.min(seg.text.length, Math.floor(elapsed * 1.8));
      urlText += seg.text.slice(0, charsToShow);
    }
  }

  const urlPulse = frame >= 140
    ? interpolate(frame, [140, 155, 165], [0, 1, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      })
    : 0;

  const cursorProgress = spring({ frame, fps: f, delay: 35, config: { damping: 160 } });
  const cursorX = interpolate(cursorProgress, [0, 1], [2600, 3100]);
  const cursorY = interpolate(cursorProgress, [0, 1], [800, 1000]);

  const cursor2Progress = spring({ frame: Math.max(0, frame - 70), fps: f, delay: 0, config: { damping: 160 } });
  const cursor2X = interpolate(cursor2Progress, [0, 1], [3100, 3100]);
  const cursor2Y = interpolate(cursor2Progress, [0, 1], [1000, 1240]);

  const cursor3Progress = spring({ frame: Math.max(0, frame - 108), fps: f, delay: 0, config: { damping: 160 } });
  const cursor3X = interpolate(cursor3Progress, [0, 1], [3100, 3100]);
  const cursor3Y = interpolate(cursor3Progress, [0, 1], [1240, 1480]);

  const activeCursorX = frame < 70 ? cursorX : frame < 108 ? cursor2X : cursor3X;
  const activeCursorY = frame < 70 ? cursorY : frame < 108 ? cursor2Y : cursor3Y;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 120,
        }}
      >
        {/* Panel */}
        <div
          style={{
            width: 2000,
            backgroundColor: "rgba(18,18,22,0.96)",
            borderRadius: 32,
            border: "2px solid rgba(255,255,255,0.09)",
            overflow: "hidden",
            opacity: titleProgress,
            transform: `scale(${interpolate(titleProgress, [0, 1], [0.96, 1])})`,
          }}
        >
          {/* Header */}
          <div
            style={{
              padding: "44px 60px 36px",
              borderBottom: "1.5px solid rgba(255,255,255,0.07)",
              display: "flex",
              alignItems: "center",
              gap: 24,
            }}
          >
            <Img src={staticFile("assets/apify/Apify symbol white.svg")} style={{ height: 52 }} />
            <div>
              <div style={{ fontSize: 44, fontWeight: 800, color: COLORS.white }}>
                Configure MCP Server
              </div>
              <div style={{ fontSize: 30, color: COLORS.muted, marginTop: 4 }}>
                Select Actors to expose as AI tools
              </div>
            </div>
          </div>

          {/* Actor list */}
          <div style={{ padding: "36px 60px", display: "flex", flexDirection: "column", gap: 24 }}>
            {ACTORS.map((actor, i) => (
              <ActorRow
                key={i}
                actor={actor}
                checked={[actor0Checked, actor1Checked, actor2Checked][i]}
                checkFrame={[40, 78, 116][i]}
              />
            ))}
          </div>

          {/* URL bar */}
          <div
            style={{
              margin: "0 60px 48px",
              padding: "28px 36px",
              backgroundColor: "rgba(255,255,255,0.04)",
              borderRadius: 18,
              border: `2px solid ${urlPulse > 0 ? `rgba(0,200,80,${0.3 + urlPulse * 0.5})` : "rgba(255,255,255,0.08)"}`,
              boxShadow: urlPulse > 0 ? `0 0 ${40 * urlPulse}px rgba(0,200,80,${0.3 * urlPulse})` : "none",
            }}
          >
            <div style={{ fontSize: 24, color: COLORS.muted, marginBottom: 10, fontWeight: 600 }}>
              SERVER URL
            </div>
            <div
              style={{
                fontSize: 30,
                color: COLORS.apifyGreen,
                fontFamily: "monospace",
                wordBreak: "break-all",
                lineHeight: 1.5,
              }}
            >
              {urlText}
              <span
                style={{
                  display: "inline-block",
                  width: 3,
                  height: 30,
                  backgroundColor: COLORS.apifyGreen,
                  marginLeft: 4,
                  opacity: Math.sin(frame * 0.3) > 0 ? 1 : 0,
                }}
              />
            </div>
          </div>
        </div>
      </AbsoluteFill>

      {/* Cursor */}
      <svg
        style={{
          position: "absolute",
          left: activeCursorX,
          top: activeCursorY,
          pointerEvents: "none",
          filter: "drop-shadow(0 4px 12px rgba(0,0,0,0.5))",
        }}
        width="52"
        height="52"
        viewBox="0 0 52 52"
      >
        <path
          d="M8 4 L8 40 L18 30 L26 48 L32 45 L24 27 L40 27 Z"
          fill="white"
          stroke="black"
          strokeWidth="2"
        />
      </svg>
    </AbsoluteFill>
  );
};

