                borderRadius: 16,
                border: "2px solid rgba(255,255,255,0.08)",
                fontSize: 32,
                color: COLORS.apifyGreen,
                fontFamily: "monospace",
                transform: `translateX(${chipX}px)`,
                opacity: chipOpacity,
              }}
            >
              https://mcp.apify.com/sse?actors=apify~rag-web-browser+apify~google-search-scraper+apify~instagram-scraper
            </div>
          </div>

          {/* Copy button */}
          <div style={{ display: "flex", justifyContent: "flex-end", opacity: btnProgress }}>
            <div
              style={{
                backgroundColor: COLORS.apifyGreen,
                borderRadius: 18,
                padding: "28px 72px",
